import React, { FC, useState } from "react";
import { useTranslation } from "react-i18next";
import { AppButton } from "@shared/form/button";
import { useGetUsers } from '@hooks/useUser';

interface IProps {
  children?: React.ReactNode
}

const HomeScreen: FC<IProps> = () => {
  const [isLoading, setLoading] = useState(false);
  const userStatus = useGetUsers({
    page: 1,
    size: 20,
  });
  console.log("userStatus", userStatus)
  const { t } = useTranslation();
  const onClisk = () => {
    setLoading(true)
  }
  return (
    <div className="page">
      <h1>Hello HomeScreen</h1>
      <AppButton variant="contained" color="secondary" text={t("common.title")} isLoading={isLoading} />
      <div>
        <button onClick={onClisk}>set Loading</button>
      </div>
    </div>
  );
};

export default HomeScreen;